def _trunc_summary(self, trace_text):
    return (
        "\n".join([l for l in str(trace_text).splitlines() if "ERROR" in l][-1:])
        + "\n"
        + "\n".join(str(trace_text).splitlines()[-10:])
    )

def _trunc_summary(self, trace_text):
    lines = str(trace_text).splitlines()
    seen = set()
    out = []
    for ln in lines:
        if ln not in seen:
            seen.add(ln)
            out.append(ln)
    return "\n".join(out)[-500:]

